namespace CharityCrm.Core.Entities;

public enum BillingInterval
{
    Monthly,
    Yearly,
}

public enum MemberStatus
{
    Active,
    Inactive,
}

/// <summary>A person whose membership is managed. Members never log in and are never physically deleted.</summary>
public class Member
{
    public const string DefaultCountry = "Österreich";

    public Guid Id { get; set; }

    /// <summary>
    /// "M-000001", generated by the database sequence <c>member_number_seq</c>; immutable.
    /// Left null until saved so EF Core lets the database default generate it.
    /// </summary>
    public string MemberNumber { get; set; } = null!;

    public string FirstName { get; set; } = "";
    public string LastName { get; set; } = "";
    public DateOnly DateOfBirth { get; set; }
    public string Street { get; set; } = "";
    public string PostalCode { get; set; } = "";
    public string City { get; set; } = "";
    public string Country { get; set; } = DefaultCountry;
    public string? Email { get; set; }
    public string? Phone { get; set; }
    public BillingInterval BillingInterval { get; set; }
    public MemberStatus Status { get; set; } = MemberStatus.Active;
    public DateOnly JoinDate { get; set; }
    public DateOnly? LeaveDate { get; set; }
    public string? LeaveReason { get; set; }
    public string? Notes { get; set; }
    public DateTimeOffset CreatedAt { get; set; }
    public DateTimeOffset UpdatedAt { get; set; }

    /// <summary>Optimistic concurrency token (PostgreSQL xmin).</summary>
    public uint RowVersion { get; set; }
}
